def iter_raw(self, chunk_size: int | None = None) -> typing.Iterator[bytes]:
    """
    A byte-iterator over the raw response content.
    """
    if self.is_stream_consumed:
        raise StreamConsumed()
    if self.is_closed:
        raise StreamClosed()
    if not isinstance(self.stream, SyncByteStream):
        raise RuntimeError("Attempted to call a sync iterator on an async stream.")

    self.is_stream_consumed = True
    self._num_bytes_downloaded = 0
    chunker = ByteChunker(chunk_size=chunk_size)

    with request_context(request=self._request):
        for raw_stream_bytes in self.stream:
            self._num_bytes_downloaded += len(raw_stream_bytes)
            for chunk in chunker.decode(raw_stream_bytes):
                yield chunk

    for chunk in chunker.flush():
        yield chunk

    self.close()

def close(self) -> None:
    """
    Close the response and release the connection.
    Automatically called if the response body is read to completion.
    """
    if not isinstance(self.stream, SyncByteStream):
        raise RuntimeError("Attempted to call a sync close on an async stream.")

    if not self.is_closed:
        self.is_closed = True
        with request_context(request=self._request):
            self.stream.close()

def _iter_json_lines(text_iter: typing.Iterator[str]) -> typing.Iterator[typing.Any]:
    """
    Parse newline-delimited JSON, yielding one value per non-blank line.
    """
    buffer = ""
    seen_data = False

    def parse_line(line: str) -> typing.Iterator[typing.Any]:
        nonlocal seen_data
        if not line.strip(_JSON_WHITESPACE):
            return
        if not seen_data:
            seen_data = True
            if line.startswith("\ufeff"):
                line = line[1:]
        try:
            yield jsonlib.loads(line)
        except jsonlib.JSONDecodeError as exc:
            raise DecodingError(str(exc)) from exc

    for text in text_iter:
        buffer += text
        if "\n" not in buffer and "\r" not in buffer:
            continue
        parts = re.split(r"\r\n|\r|\n", buffer)
        if buffer.endswith(("\r", "\n")):
            lines = parts
            buffer = ""
        else:
            lines = parts[:-1]
            buffer = parts[-1]
        for line in lines:
            yield from parse_line(line)

def iter_multipart(self) -> typing.Iterator[MultipartPart]:
    """
    Iterator over the multipart parts of the response.
    """
    if hasattr(self, "_content"):
        decoder = MultipartDecoder(self.headers.get("content-type"), self._content)
        yield from decoder.parts
    else:
        if self.is_stream_consumed:
            raise StreamConsumed()
        if self.is_closed:
            raise StreamClosed()
        if not isinstance(self.stream, SyncByteStream):
            raise RuntimeError(
                "Attempted to call a sync iterator on an async stream."
            )

        decoder = MultipartDecoder(self.headers.get("content-type"), self.stream)
        self.is_stream_consumed = True
        self._num_bytes_downloaded = 0
        with request_context(request=self._request):
            yield from decoder.iter_parts()
        self.close()
